const $=s=>document.querySelector(s), E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const token=location.hash.slice(1)||sessionStorage.getItem('camelclip-session');
if(location.hash){sessionStorage.setItem('camelclip-session',token);history.replaceState(null,'',location.pathname)}
